create or replace function public.submit_schoolpro_application(p_school uuid,p_first text,p_last text,p_gender text,p_dob date,p_guardian text,p_phone text,p_email text,p_class text,p_previous text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare aid uuid;anum text;tok uuid;begin if not exists(select 1 from public.schoolpro_site_settings s where s.school_id=p_school and s.is_published=true and s.admissions_open=true) then raise exception 'Admissions are not currently open';end if;if nullif(trim(p_first),'') is null or nullif(trim(p_last),'') is null or nullif(trim(p_guardian),'') is null or nullif(trim(p_phone),'') is null or nullif(trim(p_class),'') is null then raise exception 'Required application details are missing';end if;anum:='APP-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));insert into public.schoolpro_admissions(school_id,applicant_name,first_name,last_name,gender,date_of_birth,guardian_name,guardian_contact,guardian_email,class_applied,previous_school,application_number,status,submitted_at) values(p_school,trim(p_first)||' '||trim(p_last),trim(p_first),trim(p_last),p_gender,p_dob,trim(p_guardian),trim(p_phone),lower(trim(p_email)),trim(p_class),p_previous,anum,'pending',now()) returning id,public_token into aid,tok;return jsonb_build_object('application_id',aid,'application_number',anum,'public_token',tok);end$$;revoke all on function public.submit_schoolpro_application(uuid,text,text,text,date,text,text,text,text,text) from public;grant execute on function public.submit_schoolpro_application(uuid,text,text,text,date,text,text,text,text,text) to anon,authenticated;